Step 1 — Write a Thought and an Action block:

Thought: The goal is to create an $n \times n$ matrix where no row or column contains $k$ adjacent unoccupied squares. We can use a backtracking approach to achieve this.
Action: run_python

```python
def place_pawns(n, k):
    def is_valid(board, row, col):
        # Check row
        count = 0
        for c in range(col, min(col + k, n)):
            if board[row][c] == 0:
                count += 1
            else:
                count = 0
            if count == k:
                return False
        # Check column
        count = 0
        for r in range(row, min(row + k, n)):
            if board[r][col] == 0:
                count += 1
            else:
                count = 0
            if count == k:
                return False
        return True

    def backtrack(board, row, col):
        if row == n:
            return True
        if col == n:
            return backtrack(board, row + 1, 0)
        for pawn in [1, 0]:
            board[row][col] = pawn
            if is_valid(board, row, col) and backtrack(board, row, col + 1):
                return True
            board[row][col] = 0
        return False

    board = [[0]*n for _ in range(n)]
    if not backtrack(board, 0, 0):
        return None
    return board

n = 21
k = 14
board = place_pawns(n, k)
if board is not None:
    print("\n".join([" ".join(map(str, row)) for row in board]))
else:
    print("No solution found")
